 "content": "def transform(grid):
    """Copy each enclosed color pattern into empty frames of matching interior size."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    frames = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        # A frame has a complete one-cell border of its own color and only
        # background or that color in its interior.
        border_ok = all(grid[r0][c] == color and grid[r1][c] == color
                        for c in range(c0, c1+1))
        border_ok = border_ok and all(grid[r][c0] == color and grid[r][c1] == color
                                      for r in range(r0, r1+1))
        if not border_ok:
            continue
        if any(grid[r][c] not in (0, color)
               for r in range(r0+1, r1) for c in range(c0+1, c1)):
            continue
        pattern = [[grid[r][c] == color for c in range(c0+1, c1)]
                   for r in range(r0+1, r1)]
        frames.append((color, r0, r1, c0, c1, pattern))

    sources = [f for f in frames if any(any(row) for row in f[5])]
    for color, r0, r1, c0, c1, pattern in frames:
        if any(any(row) for row in pattern):
            continue
        ih, iw = r1-r0-1, c1-c0-1
        source = next((f for f in sources
                       if len(f[5]) == ih and len(f[5][0]) == iw), None)
        if source is None:
            continue
        src_pattern = source[5]
        for dr in range(ih):
            for dc in range(iw):
                if src_pattern[dr][dc]:
                    out[r0+1+dr][c0+1+dc] = color
    return out
