 "content": "def transform(grid):
    """Match rectangular frames by interior dimensions and propagate their pattern."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    frames = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if not (all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1+1))
                and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1+1))):
            continue
        if any(grid[r][c] not in (0, color)
               for r in range(r0+1, r1) for c in range(c0+1, c1)):
            continue
        pattern = [[grid[r][c] == color for c in range(c0+1, c1)]
                   for r in range(r0+1, r1)]
        frames.append({"color": color, "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                       "ih": r1-r0-1, "iw": c1-c0-1, "pattern": pattern})

    groups = {}
    for f in frames:
        groups.setdefault((f["ih"], f["iw"]), []).append(f)

    # A frame survives only when another frame has the same interior size.
    # Any marked pattern in a group is copied to its blank peers.
    for group in groups.values():
        if len(group) == 1:
            f = group[0]
            for r in range(f["r0"], f["r1"]+1):
                for c in range(f["c0"], f["c1"]+1):
                    out[r][c] = 0
            continue
        patterned = [f for f in group if any(any(row) for row in f["pattern"])]
        if patterned:
            src = patterned[0]["pattern"]
            for f in group:
                if any(any(row) for row in f["pattern"]):
                    continue
                for dr in range(f["ih"]):
                    for dc in range(f["iw"]):
                        if src[dr][dc]:
                            out[f["r0"]+1+dr][f["c0"]+1+dc] = f["color"]
    return out
